type membrane struct {
    mu   sync.RWMutex
    dead bool
    t    Dir
    wr   map[*entry]File          // identity map keyed on the raw object
}

func (m *membrane) Open(p string) (File, error) {
    if m.revoked() { return nil, ErrRevoked }   // check and forward together
    f, err := m.t.Open(p)
    return m.wrap(f), err                       // wrap the way out
}
